    margins = list(csv.DictReader(open(P / 'DECISION_MARGINS.csv')))
    prep = list(csv.DictReader(open(P / 'PREPARATION_MARGINS.csv')))
    records = list(map(json.loads, open(P / 'RAW_R1_SITE_GUARDS.jsonl')))
    rb = [r for r in records if r.get('selection') == 'ARCHIVED_RB']
    status = Counter((x['scenario_status'] for x in margins if x['selection'] == 'ARCHIVED_RB'))
    tight = min(prep, key=lambda x: float(x['signed_margin_mm']))
    data = json.load(open(P / 'DATA_MANIFEST.json'))
    data3 = json.load(open(P / 'DATA_MANIFEST_R3.json'))
    aa = np.load(data[-1]['path'])
    pp = np.array(pairs[-1]['adverse_added_voxel'], dtype=np.int32)
